/** A piece of the set by name, at its own size unless told another. */
export function PaperbackArt({ name, width, height, style, ...rest }) {
  const a = ART[name]
  return (
    <svg
      viewBox={a.vb} width={width ?? a.w} height={height ?? a.h} fill="none" aria-hidden="true"
      style={{ display: 'block', overflow: 'visible', ...style }} {...rest}
      dangerouslySetInnerHTML={{ __html: a.body }}
    />
  )
}

/** The four-point sparkle: `fill` its body, `ink` its outline. */
export function PaperbackSparkle({ size = 16, fill = '#FFD24A', ink = '#0B0B0B', style, ...rest }) {
  return (
    <svg viewBox="0 0 16 16" width={size} height={size} fill="none" aria-hidden="true" style={{ display: 'block', overflow: 'visible', ...style }} {...rest}>
      <path d="M8 0C8.64 5.76 10.24 7.36 16 8C10.24 8.64 8.64 10.24 8 16C7.36 10.24 5.76 8.64 0 8C5.76 7.36 7.36 5.76 8 0Z" fill={fill} stroke={ink} strokeWidth="0.8" strokeLinejoin="round" />
    </svg>
  )
}

